import{_ as t,o,c as a,a5 as r}from"./chunks/framework.QnCkLuYX.js";const n="/assets/unsaved-diff.C8eqBYwG.png",i="/assets/reimport-review.BV8DfEH4.png",s="/assets/export-wizard.XLg8FK3Z.png",f=JSON.parse('{"title":"Saving and Exporting","description":"","frontmatter":{},"headers":[],"relativePath":"en_US/07-saving-and-exporting.md","filePath":"en_US/07-saving-and-exporting.md"}'),l={name:"en_US/07-saving-and-exporting.md"};function c(d,e,p,h,u,g){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="saving-and-exporting" tabindex="-1">Saving and Exporting <a class="header-anchor" href="#saving-and-exporting" aria-label="Permalink to &quot;Saving and Exporting&quot;">​</a></h1><p>Protect work in progress, review unsaved changes, re-import safely, and produce delivery files.</p><h2 id="what-you-can-do-on-this-page" tabindex="-1">What you can do on this page <a class="header-anchor" href="#what-you-can-do-on-this-page" aria-label="Permalink to &quot;What you can do on this page&quot;">​</a></h2><ul><li>Save a project or legacy CSV workspace.</li><li>Compare current rows with the saved version.</li><li>Recover drafts and review subtitle re-import alignment.</li><li>Export XLSX, SRT, or styled ASS files.</li></ul><h2 id="save-a-project" tabindex="-1">Save a project <a class="header-anchor" href="#save-a-project" aria-label="Permalink to &quot;Save a project&quot;">​</a></h2><p>Use <code>Ctrl+S</code> (<code>Command+S</code> on macOS) or <strong>Save</strong>. Project mode writes the managed workspace and project metadata in the project folder. A successful save clears the draft warning; save before changing resources, replacing a license, updating, or closing the app.</p><p>Do not edit <code>workspace.csv</code> externally while the project is open. Concurrent external changes can produce a conflict that must be resolved explicitly.</p><h2 id="review-unsaved-changes" tabindex="-1">Review unsaved changes <a class="header-anchor" href="#review-unsaved-changes" aria-label="Permalink to &quot;Review unsaved changes&quot;">​</a></h2><p>Click the draft/unsaved-diff indicator to compare the last saved version with current rows.</p><p><img src="'+n+'" alt="Unsaved Diff menu showing saved and current row values"></p><p>The view summarizes visible changed rows and line-level differences. It is a review tool, not an alternative save format.</p><h2 id="recover-unsaved-work" tabindex="-1">Recover unsaved work <a class="header-anchor" href="#recover-unsaved-work" aria-label="Permalink to &quot;Recover unsaved work&quot;">​</a></h2><p>GridSubStudio maintains project drafts to help recover after an unexpected close. When recovery is offered, compare the draft timestamp and content before restoring. Save formally after confirming recovery.</p><p>Draft recovery does not replace backups and should not be treated as the only copy of important work.</p><h2 id="re-import-subtitles" tabindex="-1">Re-import subtitles <a class="header-anchor" href="#re-import-subtitles" aria-label="Permalink to &quot;Re-import subtitles&quot;">​</a></h2><p>In <strong>Project Setup → Import</strong>, choose <strong>Import Original</strong> or <strong>Import Translation</strong>. The mode dialog explains the two choices:</p><ul><li><strong>Precise Update</strong> aligns old and new rows in the imported episodes and preserves compatible content from the other subtitle track.</li><li><strong>Whole Replacement</strong> rebuilds each episode matched by this import without alignment. Old rows, edits, and other-track content in those episodes are removed, while episodes not matched by this import stay unchanged.</li></ul><p>GridSubStudio opens an alignment review only for <strong>Precise Update</strong> when imported rows do not align exactly.</p><p><img src="'+i+'" alt="Subtitle import alignment review showing timing shifts and unmatched rows"></p><p>Review exact matches, tolerated timing shifts, splits, merges, unmatched source rows, and new imported rows. <strong>Continue Import</strong> applies the displayed plan; <strong>Cancel Import</strong> leaves the current workspace unchanged.</p><p>Subtitle <strong>Whole Replacement</strong> clears the existing undo and redo history. Save the project before using it when you may need to recover the replaced episode contents.</p><h2 id="save-a-legacy-csv" tabindex="-1">Save a legacy CSV <a class="header-anchor" href="#save-a-legacy-csv" aria-label="Permalink to &quot;Save a legacy CSV&quot;">​</a></h2><p>In legacy CSV mode, <strong>Save</strong> updates the current CSV and <strong>Save As</strong> creates another file. Preserve the semicolon-delimited schema and required columns. Project-only resource and subtitle export workflows are not available until migration.</p><h2 id="export-xlsx" tabindex="-1">Export XLSX <a class="header-anchor" href="#export-xlsx" aria-label="Permalink to &quot;Export XLSX&quot;">​</a></h2><p>Use XLSX export to create a review workbook from the current workspace. Confirm filters and row scope before export. XLSX is a delivery/review artifact; continue editing the project or CSV as the source of truth.</p><h2 id="export-srt-or-ass" tabindex="-1">Export SRT or ASS <a class="header-anchor" href="#export-srt-or-ass" aria-label="Permalink to &quot;Export SRT or ASS&quot;">​</a></h2><p>Click <strong>Export</strong> to open the wizard.</p><p><img src="'+s+'" alt="Export wizard with SRT format, translation content, naming, and three-file preview"></p><ol><li>Choose <strong>SRT</strong> or <strong>ASS</strong>.</li><li>Choose source, translation, or bilingual content.</li><li>Select the output folder.</li><li>Set the filename template and episode padding.</li><li>Review row/episode counts and filename preview.</li><li>Click <strong>Export</strong>.</li></ol><h2 id="configure-ass-styles" tabindex="-1">Configure ASS styles <a class="header-anchor" href="#configure-ass-styles" aria-label="Permalink to &quot;Configure ASS styles&quot;">​</a></h2><p>ASS export requires a style/template source. Use the imported ASS/SSA source template when available, choose another valid template, or select the minimal style option if offered. SRT has no ASS style requirement.</p><p>Review dialogue styles, line breaks, and event metadata in a subtitle player after export.</p><h2 id="configure-content-and-filenames" tabindex="-1">Configure content and filenames <a class="header-anchor" href="#configure-content-and-filenames" aria-label="Permalink to &quot;Configure content and filenames&quot;">​</a></h2><ul><li><strong>Field</strong> selects source or translation.</li><li><strong>Bilingual</strong> combines both fields in each subtitle event.</li><li>The filename template must include <code>{episode}</code> for multi-episode output.</li><li><strong>Episode Digits / Leading Zero</strong>: enter a digit count from 1 to 4; new projects default to 2. Enable Leading Zero to produce values such as <code>01</code> or <code>001</code>. Existing projects retain their saved digit count.</li><li>The preview exposes duplicate filenames before writing.</li></ul><p>Existing files may require overwrite confirmation. Never rely on the preview alone; inspect exported files before delivery.</p><h2 id="handle-export-restrictions" tabindex="-1">Handle export restrictions <a class="header-anchor" href="#handle-export-restrictions" aria-label="Permalink to &quot;Handle export restrictions&quot;">​</a></h2><p>Project subtitle export requires a valid license. Without one, the wizard can still open and show settings, but the final <strong>Export</strong> button is disabled. See <a href="./09-license-management.html">License Management</a>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>Export is disabled:</strong> verify license status, application version coverage, and the current computer&#39;s license.</li><li><strong>ASS template is required:</strong> import an ASS/SSA source or select a valid style source.</li><li><strong>Filenames conflict:</strong> include <code>{episode}</code> or change padding/template.</li><li><strong>Output cannot be written:</strong> choose a writable folder and close files held by another application.</li><li><strong>Rows are missing:</strong> clear unintended filters and verify episode scope/content selection.</li></ul>',39)])])}const v=t(l,[["render",c]]);export{f as __pageData,v as default};
